//! 🎟️ Original read Work laws use the same finite decoder Source and actual receipts.
use super::*;
use semio_framework_value_read::retained_clone::OriginalSourceMode;

fn law()->serde_json::Value{let value:serde_json::Value=serde_json::from_str(include_str!("../../🎟️work/case.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("../../🎟️work/case.schema.json")).unwrap();for(key,row)in value.as_object().unwrap(){assert_eq!(&schema["properties"][key]["const"],row)}value}
fn actor<T:RetireOwned+Sync>(value:T,turn:OriginalSourceTurnIdentity)->OriginalEffectAuthority<IssueProducer<T>>{OriginalEffectAuthority::new(IssueProducer{birth:ManuallyDrop::new(ReadRegistryBirth::new()),issued:ManuallyDrop::new(None),authority:ManuallyDrop::new(None),aliases:ManuallyDrop::new(std::array::from_fn(|_|None)),value:Some(value),inputs:ManuallyDrop::new(std::array::from_fn(|_|None)),stored:ManuallyDrop::new(std::array::from_fn(|_|None)),root:ManuallyDrop::new(None),issue:ManuallyDrop::new(None),lease:ManuallyDrop::new(None),visit:ManuallyDrop::new(None),erased:ManuallyDrop::new(None),root_close:ManuallyDrop::new(None),typed_source:ManuallyDrop::new(None),typed_owner:ManuallyDrop::new(Default::default()),typed_action:None,typed_reply:ManuallyDrop::new(None),wrong_reply:ManuallyDrop::new(None),source:ManuallyDrop::new(None),owner:ManuallyDrop::new(Default::default()),owner_action:None,owner_reply:ManuallyDrop::new(None),cursor:ManuallyDrop::new(None),cursor_reply:ManuallyDrop::new(None),turn})}
fn setup<T:RetireOwned+Sync>(bank:&mut source_bank::Bank,native:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<OriginalRetirementFailure>,actor:&mut OriginalEffectAuthority<IssueProducer<T>>){for _ in 0..65536{if actor.inspect(|p|p.birth.ready()){break}sparse::turn(bank,native,frame,actor,IssueOp::Birth);}assert!(actor.inspect(|p|p.birth.ready()));sparse::turn(bank,native,frame,actor,IssueOp::Take);sparse::turn(bank,native,frame,actor,IssueOp::Authority);sparse::turn(bank,native,frame,actor,IssueOp::Root);sparse::turn(bank,native,frame,actor,IssueOp::IssueBirth);for _ in 0..16{if actor.inspect(|p|p.lease.is_some()){break}sparse::turn(bank,native,frame,actor,IssueOp::Issue);}assert!(actor.inspect(|p|p.lease.is_some()));sparse::turn(bank,native,frame,actor,IssueOp::IssueReturn);sparse::turn(bank,native,frame,actor,IssueOp::IssueClear);}
fn close<T:RetireOwned+Sync>(bank:&mut source_bank::Bank,native:&mut NativeDecodeControl<'_>,frame:&mut NativeReceivingEffect<OriginalRetirementFailure>,actor:&mut OriginalEffectAuthority<IssueProducer<T>>)->bool{let mut scan=false;for _ in 0..65536{if actor.inspect(|p|p.lease.as_ref().unwrap().terminal_is_empty()){break}let original=actor.inspect(|p|p.lease.as_ref().unwrap().requires_original_control());sparse::turn(bank,native,frame,actor,if original{IssueOp::LeaseOriginal}else{IssueOp::Lease});}assert!(actor.inspect(|p|p.lease.as_ref().unwrap().terminal_is_empty()));sparse::turn(bank,native,frame,actor,IssueOp::LeaseClear);for _ in 0..65536{if actor.inspect(|p|p.authority.as_ref().unwrap().terminal_is_empty()){break}let original=actor.inspect(|p|p.authority.as_ref().unwrap().requires_original_control());let work=actor.inspect(|p|p.authority.as_ref().unwrap().next_computational_work(4096).unwrap());let before=bank.wallet.lock().unwrap().fuel;sparse::turn(bank,native,frame,actor,if original{IssueOp::AuthorityOriginal}else{IssueOp::AuthorityClose});if work==18{assert_eq!(before-bank.wallet.lock().unwrap().fuel,18);scan=true}}assert!(actor.inspect(|p|p.authority.as_ref().unwrap().terminal_is_empty()));sparse::turn(bank,native,frame,actor,IssueOp::AuthorityClear);scan}

pub(crate) fn run_read_work(){
 let row=law();let mut bank=source_bank::Bank::from_stock(&row["stock"],false);let mut recipient=NativeDecodeRetirementRecipient::new();let mut observer=|_|true;let mut native=NativeDecodeControl::new(row["stock"]["capacityBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut frame=NativeReceivingEffect::default();let mut actor=actor(19u64,bank.turn.identity());setup(&mut bank,&mut native,&mut frame,&mut actor);let id=actor.inspect(|p|p.lease.as_ref().unwrap().id());let before=bank.wallet.lock().unwrap().fuel;sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::LeaseShort);assert_eq!(before-bank.wallet.lock().unwrap().fuel,row["deniedWork"].as_u64().unwrap()as u128);assert_eq!(actor.inspect(|p|*p.lease.as_ref().unwrap().get()),19);
 let before=bank.wallet.lock().unwrap().fuel;sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Lease);assert_eq!(before-bank.wallet.lock().unwrap().fuel,row["readAliasReturnWork"].as_u64().unwrap()as u128);assert!(actor.inspect(|p|p.authority.as_ref().unwrap().registry().unwrap().contains(id).unwrap()));
 let before=bank.wallet.lock().unwrap().fuel;sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Lease);assert_eq!(before-bank.wallet.lock().unwrap().fuel,row["closingChildHandoffWork"].as_u64().unwrap()as u128);let(mut election,mut header)=(false,false);for _ in 0..16{if actor.inspect(|p|p.lease.as_ref().unwrap().terminal_is_empty()){break}let before=bank.wallet.lock().unwrap().fuel;let quote=actor.inspect(|p|p.lease.as_ref().unwrap().next_computational_work(4096).unwrap());let original=actor.inspect(|p|p.lease.as_ref().unwrap().requires_original_control());let step=sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,if original{IssueOp::LeaseOriginal}else{IssueOp::Lease});let actual=before-bank.wallet.lock().unwrap().fuel;assert_eq!(actual,quote as u128);if actual==row["aliasElectionWork"].as_u64().unwrap()as u128{election=true}if step.progress().released_bytes>0{assert_eq!(actual,row["completedChildHeaderWork"].as_u64().unwrap()as u128);header=true;break}assert!(actor.inspect(|p|p.authority.as_ref().unwrap().registry().unwrap().contains(id).unwrap()));}assert!(election&&header);
 for _ in 0..65536{if actor.inspect(|p|p.lease.as_ref().unwrap().terminal_is_empty()){break}let original=actor.inspect(|p|p.lease.as_ref().unwrap().requires_original_control());sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,if original{IssueOp::LeaseOriginal}else{IssueOp::Lease});}assert!(actor.inspect(|p|p.lease.as_ref().unwrap().terminal_is_empty()));let before=bank.wallet.lock().unwrap().fuel;let step=sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::Lease);assert_eq!(before-bank.wallet.lock().unwrap().fuel,row["cachedWork"].as_u64().unwrap()as u128);assert!(matches!(step,RetainedCloneStep::Complete(progress)if progress==Default::default()));assert!(close(&mut bank,&mut native,&mut frame,&mut actor));assert!(actor.inspect(IssueProducer::terminal));drop(actor.into_producer().ok().unwrap());
}

pub(crate) fn run_source_null(){
 let row=law();let(value,initial)=semio_framework_value_testing_allocator::observe_retirement_allocations(||"owned λ".to_owned());assert_eq!(initial.1,0);let bytes=value.as_ptr()as usize;let mut bank=source_bank::Bank::from_stock(&row["stock"],false);let mut recipient=NativeDecodeRetirementRecipient::new();let mut observer=|_|true;let mut native=NativeDecodeControl::new(row["stock"]["capacityBytes"].as_u64().unwrap()as usize,&mut observer);native.install_retirement_recipient(&mut recipient).unwrap();let mut frame=NativeReceivingEffect::default();let mut actor=actor(value,bank.turn.identity());setup(&mut bank,&mut native,&mut frame,&mut actor);let address=actor.inspect(|p|p.lease.as_ref().unwrap().get()as*const String as usize);sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::TypedCapture);sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::TypedOwnerCapture);
 for _ in 0..65536{let demand=actor.inspect(|p|p.typed_owner.demand(OriginalSourceMode::Original,4096).unwrap().unwrap());let drive=actor.inspect(|p|p.typed_owner.projection_drive_required_for(OriginalSourceMode::Original).unwrap());if !drive&&demand.capacity_bytes>0{break}sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,if drive{IssueOp::TypedOwnerDrive}else{IssueOp::TypedOwnerOriginal});}
 assert!(actor.inspect(|p|p.typed_owner.demand(OriginalSourceMode::Original,4096).unwrap().unwrap().capacity_bytes>0));let before=bank.wallet.lock().unwrap().fuel;let(_,attempts)=semio_framework_value_testing_allocator::refuse_one_allocation_on_this_thread(||sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::TypedOwnerProbe));assert_eq!(attempts,1);assert_eq!(before-bank.wallet.lock().unwrap().fuel,(row["nullAllocationAttemptWork"].as_u64().unwrap()+row["nullReplyCaptureWork"].as_u64().unwrap())as u128);
 actor.inspect(|p|{let error=p.wrong_reply.as_ref().unwrap().as_ref().err().unwrap();assert_eq!(error.primary().unwrap().kind,ValueRefusalKind::AllocationFailed);let original=p.typed_owner.original_authority().unwrap().get();assert_eq!(original as*const String as usize,address);assert_eq!(original.as_ptr()as usize,bytes);assert_eq!(original.as_str(),"owned λ")});sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::ProbeClear);
 for _ in 0..65536{let pending=actor.inspect(|p|p.typed_owner.demand(OriginalSourceMode::Unique,4096).unwrap().is_some());if !pending{break}let drive=actor.inspect(|p|p.typed_owner.projection_drive_required_for(OriginalSourceMode::Unique).unwrap());let original=actor.inspect(|p|p.typed_owner.requires_original_control());sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,if drive{IssueOp::TypedOwnerDriveUnique}else if original{IssueOp::TypedOwnerUniqueOriginal}else{IssueOp::TypedOwnerUnique});}
 assert_eq!(actor.inspect(|p|p.typed_owner.unique().unwrap().get()as*const String as usize),address);sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::TypedOwnerReturn);sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::TypedReturn);sparse::turn(&mut bank,&mut native,&mut frame,&mut actor,IssueOp::TypedClear);assert_eq!(actor.inspect(|p|p.lease.as_ref().unwrap().get()as*const String as usize),address);assert!(close(&mut bank,&mut native,&mut frame,&mut actor));assert!(actor.inspect(IssueProducer::terminal));drop(actor.into_producer().ok().unwrap());let wallet=bank.wallet.lock().unwrap();assert_eq!(wallet.spent.released_bytes,wallet.spent.retained_capacity_bytes+initial.0);
}

